# Sessions: (book, chapter, [verses]) ; verse may be "1b" for part-verses
def R(book, ch, *vs):
    out = []
    for v in vs:
        if isinstance(v, tuple): out += list(range(v[0], v[1] + 1))
        else: out.append(v)
    return (book, ch, out)

